const cfg = $('Merge Config').first().json;
const bal = $input.first().json || {};
return [{
  json: {
    ...cfg,
    balance_before: bal,
  }
}];

const cfg = $('Attach Balance Before').first().json;
const limit = Number(cfg.limit) || 0;
const pidFilter = String(cfg.product_id_filter || '').trim();
let rows = items.map((i) => i.json);
if (pidFilter) {
  rows = rows.filter((r) => String(r.product_id || '') === pidFilter);
}
if (limit > 0) {
  rows = rows.slice(0, limit);
}
return rows.map((r) => ({
  json: {
    ...r,
    _cfg_model: cfg.model,
    _cfg_prompt_system: cfg.prompt_system,
    _cfg_prompt_user_template: cfg.prompt_user_template,
    _cfg_source: cfg.source,
    _cfg_started_at: cfg.started_at,
    _cfg_balance_before: cfg.balance_before,
    _cfg_limit: limit,
  }
}));

const row = items[0].json;
const system = String(row._cfg_prompt_system || '');
const tmpl = String(row._cfg_prompt_user_template || "Найди МНН для препарата '{normalized_text}'");
const text = String(row.normalized_text || '').trim();
const user = tmpl.split('{normalized_text}').join(text);
const started = Date.now();
return [{
  json: {
    ...row,
    prompt_system: system,
    prompt_user: user,
    _http_started_ms: started,
  }
}];

const raw = (typeof query === 'string') ? query : (query && (query.query || query.q || query.input)) || '';
const q = String(raw || '').trim();
if (!q) return 'empty query';
const url = 'https://lite.duckduckgo.com/lite/?kl=ru-ru&q=' + encodeURIComponent(q + ' site:.ru');
let html = '';
try {
  html = await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: {
      'User-Agent': 'Mozilla/5.0 (compatible; n8n-mnn-agent/1.0)',
      'Accept': 'text/html',
    },
    encoding: 'text',
    returnFullResponse: false,
  });
} catch (e) {
  return 'search_error: ' + String(e && e.message ? e.message : e);
}
const text = String(html || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim();
return text.slice(0, 3500) || 'no_results';

const prep = $('Build Prompt').item.json;
const agent = items[0].json || {};

function extractJson(text) {
  if (!text) return null;
  let t = String(text).trim();
  const fence = t.match(/^```(?:json)?\s*\n?([\s\S]+?)\n?```\s*$/i);
  if (fence) t = fence[1].trim();
  const a = t.indexOf('{'); const b = t.lastIndexOf('}');
  if (a >= 0 && b > a) t = t.slice(a, b + 1);
  try { const o = JSON.parse(t); return (o && typeof o === 'object') ? o : null; } catch (e) { return null; }
}

let text = '';
if (typeof agent.output === 'string') text = agent.output;
else if (agent.output != null) text = JSON.stringify(agent.output);
else if (typeof agent.text === 'string') text = agent.text;
else if (agent.error) text = String(agent.error.message || agent.error);

const steps = agent.intermediateSteps || agent.intermediate_steps || [];
const searchUsed = Array.isArray(steps) && steps.length > 0 ? 1 : 0;
const searchCalls = Array.isArray(steps) ? steps.length : 0;
const queries = [];
for (const step of (Array.isArray(steps) ? steps : [])) {
  const action = step.action || step;
  const input = action.toolInput || action.tool_input || action.input || {};
  const q = (typeof input === 'string') ? input : (input.q || input.query || input.input || '');
  if (q) queries.push(String(q));
}

const parsed = extractJson(text);
let toolStatus = 'invalid_json';
let toolMnn = '';
if (agent.error) {
  toolStatus = 'api_error';
} else if (parsed) {
  toolStatus = String(parsed.status || 'not_found');
  if (!['found','not_found','conflict'].includes(toolStatus)) toolStatus = 'not_found';
  toolMnn = parsed.mnn == null ? '' : String(parsed.mnn).trim();
  if (!toolMnn || toolMnn.toLowerCase() === 'null') toolMnn = '';
  if (toolStatus !== 'found') toolMnn = '';
  if (toolStatus === 'found' && !toolMnn) toolStatus = 'not_found';
}

const latency = prep._http_started_ms ? (Date.now() - Number(prep._http_started_ms)) : null;

return [{
  json: {
    product_id: prep.product_id,
    run_id: prep.run_id,
    normalized_text: prep.normalized_text,
    win_mnn: prep.win_mnn,
    qwen_search_status: prep.qwen_search_status,
    qwen_search_mnn: prep.qwen_search_mnn,
    prompt_system: prep.prompt_system,
    prompt_user: prep.prompt_user,
    model: prep._cfg_model,
    tool_status: toolStatus,
    tool_mnn: toolMnn,
    search_used: searchUsed,
    search_call_count: searchCalls,
    search_queries: queries,
    raw_text: text,
    latency_ms: latency,
    prompt_tokens: 0,
    completion_tokens: 0,
    total_tokens: 0,
    api_error: agent.error ? String(agent.error.message || agent.error).slice(0, 500) : '',
    _cfg_source: prep._cfg_source,
    _cfg_started_at: prep._cfg_started_at,
    _cfg_balance_before: prep._cfg_balance_before,
  }
}];

const rows = items.map((i) => i.json);
const n = rows.length;
const found = rows.filter((r) => r.tool_status === 'found').length;
const searchUsed = rows.filter((r) => Number(r.search_used) === 1).length;
const tokens = rows.reduce((a, r) => a + Number(r.total_tokens || 0), 0);
const lat = rows.map((r) => Number(r.latency_ms || 0)).filter((x) => x > 0).sort((a,b)=>a-b);
const p50 = lat.length ? lat[Math.floor((lat.length-1)*0.5)] : null;
const first = rows[0] || {};
return [{
  json: {
    provider: 'deepseek-ai-agent',
    model: first.model || 'deepseek-chat',
    source: first._cfg_source || null,
    started_at: first._cfg_started_at || null,
    finished_at: new Date().toISOString(),
    n,
    found_count: found,
    coverage: n ? Number((found / n).toFixed(4)) : 0,
    search_used_rate: n ? Number((searchUsed / n).toFixed(4)) : 0,
    total_tokens: tokens,
    latency_p50_ms: p50,
    balance_before: first._cfg_balance_before || null,
    rows,
  }
}];

const summary = $('Summary').first().json;
const balAfter = $input.first().json || {};
return [{
  json: {
    ...summary,
    balance_after: balAfter,
    status: 'ok',
  }
}];
